  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
            (h : HST usegs L HI) (LB : list blk) (SB SAN BUF sp0 slen lo : Z) (bs : list byte).
  Notation CTX := (san_ctx usegs L HI U_CALLOC U_FREE sp tp h LB SB SAN BUF sp0 slen lo bs).
  Hypothesis HC : CTX.

  Notation X := [(SAN, SAN + 80)].
  Notation W := [(SAN, SAN + 80); (bv_unsigned sp - 80, bv_unsigned sp)].
  Notation POST := (x509_parse_san_post usegs L HI ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc h LB SAN lo m mo).
  Notation SPF := (Z_to_bv 64 (bv_unsigned sp + -80)).
  Let epi_walk' := epi_walk L HI ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m mo h LB SB SAN BUF sp0 slen lo bs HC.
  Let IBB := in_block_below' L HI sp tp h LB SB SAN BUF sp0 slen lo bs HC.
  Let heap_W' := heap_W L HI sp tp mo h LB SB SAN BUF sp0 slen lo bs HC.
  Let presx_W' := presx_W L HI sp tp m h LB SB SAN BUF sp0 slen lo bs HC.
  (* [comment removed for export] *)
  Ltac ro_const A n RO :=
    lazymatch goal with |- context [MS _ _ _ _ _ ?mx (seg_rom ?sg)] =>
      let bs := eval vm_compute in (match image_bytes sg A n with Some bs => bs | None => [] end) in
      match goal with MI : mem_inv sg mx |- _ =>
        pose proof (ro_image_bytes_at sg mx A bs MI ltac:(vm_compute; reflexivity) ltac:(lia) ltac:(cbn; lia)) as RO end
    end.

  (* [comment removed for export] *)
  Ltac san_t0 HSAN :=
    lazymatch type of HSAN with rw_cells ?sg ?mx ?A _ =>
      apply (rw_cells_zeros sg mx A 80 [C4 (Z_to_bv 64 0); CB 76 (repeat (Z_to_bv 8 0) 76)]) in HSAN;
        [| cbn; (flsplit; repeat split); reflexivity | reflexivity] end.

  (* [comment removed for export] *)
  Ltac lxjoin H1 H2 :=
    lazymatch type of H1 with rw_cells ?sg ?mm ?A1 ?cs1 =>
    lazymatch type of H2 with rw_cells _ _ ?A2 ?cs2 =>
      let v := eval vm_compute in (Z.of_nat (cells_size cs1)) in
      let Hj := fresh "J" in
      pose proof (proj2 (rw_cells_app sg mm A1 cs1 cs2)) as Hj;
      let He := fresh "E" in
      assert (He : Z.of_nat (cells_size cs1) = v) by reflexivity; rewrite He in Hj; clear He;
      replace A2 with (A1 + v) in H2 by lia;
      specialize (Hj (conj H1 H2)); clear H1 H2; rename Hj into H1; cbn [app] in H1
    end end.
  Ltac join_frame mx := repeat (
    lazymatch goal with Hf0 : rw_cells usegs mx (bv_unsigned sp + -80) ?cs0 |- _ =>
      let v := eval vm_compute in (-80 + Z.of_nat (cells_size cs0)) in
      match goal with Hf1 : rw_cells usegs mx (bv_unsigned sp + v) _ |- _ => lxjoin Hf0 Hf1 end end).
  Ltac join_san mx := repeat (
    lazymatch goal with Hf0 : rw_cells usegs mx SAN ?cs0 |- _ =>
      let v := eval vm_compute in (Z.of_nat (cells_size cs0)) in
      match goal with Hf1 : rw_cells usegs mx (SAN + v) _ |- _ => lxjoin Hf0 Hf1 end end).

  Lemma on1_walk : forall (w0x pw lw x12 x13 x14 x1 x5 x6 x7 x15 x16 x17 x18 x19 x20 x28 x29 x30 x31 : word) mm,
    rw_cells usegs mm (bv_unsigned sp + -80) [C8 pw; C8 lw; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    rw_cells usegs mm SB [C8 w0x; C8 (Z_to_bv 64 slen); C8 (Z_to_bv 64 sp0)] ->
    rw_cells usegs mm SAN [CB 80 (repeat (Z_to_bv 8 0) 80)] ->
    bytes_at usegs mm BUF bs ->
    stk usegs mm lo (bv_unsigned sp + -80) -> mem_inv usegs mm ->
    munch W m mm -> wmono usegs m mm -> HEAP usegs L HI h LB m mo ->
    aevtM usegs mo POST
      (MS (mkR x1 SPF gp tp x5 x6 x7 (Z_to_bv 64 SAN) (Z_to_bv 64 SB) (Z_to_bv 64 (-8320)) (Z_to_bv 64 128) x12 x13 x14 x15 x16 x17 x18 x19 x20 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
          F (Z_to_bv 64 0x28a28) fc None mm (seg_rom usegs))
(* [comment removed for export] *).
  Proof.
    intros w0x pw lw x12 x13 x14 x1 x5 x6 x7 x15 x16 x17 x18 x19 x20 x28 x29 x30 x31 mm FR HSB HSAN HBUF ST MI MU WM HH.
    open_sctx HC. pose proof (heap_mok _ _ HI _ _ _ _ HH) as MK.
    pose proof (bytes_at_bound _ _ _ _ HBUF) as BB.
    pose proof (bv_unsigned_in_range 64 w0x) as W0R. unfold bv_modulus in W0R. cbn in W0R.
    (* [comment removed for export] *)
    ro_const 0x10669 8%nat ROD. lazymatch type of ROD with bytes_at _ _ _ ?cbs => assert (ROL : Z.of_nat (length cbs) = 8) by reflexivity end.
    lx_byte_cells.
    (* [comment removed for export] *)
    assert (LXSUMS : forall AL, Forall (summary_okG usegs AL []) [SUM_gettagP; SUM_memset0P 80])
      by (intros AL; repeat constructor; apply apply_summary_sound; first [apply sum_gettagP_valid | apply sum_memset0P_valid; lia]).
    rewrite TP.
    apply (lxp_aevtM_of_evt usegs mo _ _ MK).
    lx_run_tac (PLANS [0x28c40; 0x46940] [] 120%N [SUM_gettagP; SUM_memset0P 80]); lx_tree.
    (* [comment removed for export] *)
    all: lazymatch goal with
         | |- evt _ _ (MS (mkR _ _ _ _ _ _ _ _ _ _ (Z_to_bv 64 ?p1) _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _) _ (Z_to_bv 64 0x46940) _ _ ?mx _) =>
             lazymatch goal with HB : bytes_at _ mx BUF bs |- _ =>
               let QBY := fresh "QBY" in let QLEN := fresh "QLEN" in
               destruct (bytes_at_sliceK mx BUF bs p1 8 HB ltac:(first [clear_disj; lia | lia]) ltac:(clear; lia) ltac:(first [clear_disj; lia | lia])) as [QBY QLEN];
               let ROD2 := fresh "ROD" in ro_const 0x10669 8%nat ROD2;
               let SPB := fresh "SPB" in pose proof U_bcmp_spec as SPB; unfold memcmp_stmt in SPB;
               eapply evt_cut;
               [ eapply SPB; rewrite ?unsigned_lit by (first [clear_disj; lia | lia]); [exact ROD2 | exact QBY | reflexivity | apply Nat2Z.inj; rewrite QLEN; reflexivity]
               | clear SPB; let ms' := fresh "ms" in let PO := fresh "PO" in intros ms' PO;
                 let r := fresh "rb" in let Hr := fresh "Hrb" in
                 (flat constr:(PO) 10%nat; flclear PO; intros ? ? ? ? ? r -> -> Hr _);
                 replace (ret_pc (Z_to_bv 64 0x28ca8)) with (Z_to_bv 64 0x28ca8 : word) by (symmetry; apply ret_pc_even; [clear; lia| reflexivity]);
                 clear QBY QLEN ROD2;
                 lx_run_tac (PLANS [0x28c40] [] 200%N [SUM_gettagP; SUM_memset0P 80]); lx_tree ]
             end
         | |- _ => idtac
         end.
    (* [comment removed for export] *)
    all: apply evt_done; cbv beta; rewrite <- TP.
    all: lazymatch goal with |- aevtM _ _ _ (MS _ _ _ _ _ ?mx _) =>
         join_frame mx; join_san mx;
         lazymatch goal with Hs : rw_cells _ mx SAN ?cs |- _ =>
           lazymatch cs with
           | [CB 80 _] => san_t0 Hs
           | C4 _ :: _ => idtac
           | CB 8 _ :: ?tl =>
               change (rw_cells usegs mx SAN cs) with (rw_cells usegs mx SAN ([CB 8 (repeat (Z_to_bv 8 0) 8)] ++ tl)) in Hs;
               apply (proj1 (rw_cells_app usegs mx SAN _ _)) in Hs;
               let Hs0 := fresh "Hs" in let Hs1 := fresh "Hs" in destruct Hs as [Hs0 Hs1];
               change (Z.of_nat (cells_size [CB 8 (repeat (Z_to_bv 8 0) 8)])) with 8 in Hs1;
               apply (rw_cells_zeros usegs mx SAN 8 [C4 (Z_to_bv 64 0); CB 4 (repeat (Z_to_bv 8 0) 4)]) in Hs0;
                 [| cbn; (flsplit; repeat split); reflexivity | reflexivity];
               lxjoin Hs0 Hs1
           end end
         end.
    all: lazymatch goal with |- aevtM _ _ _ (MS _ _ _ _ _ ?mx _) =>
         lazymatch goal with FRx : rw_cells _ mx (bv_unsigned sp + -80) _, STx : stk _ mx lo _, MIx : mem_inv _ mx, MUx : munch _ m mx, WMx : wmono _ m mx,
                             Hs : rw_cells _ mx SAN _ |- _ =>
           eapply epi_walk'; [exact FRx| exact STx| exact MIx| exact MUx| exact WMx| exact HH| first [clear_disj; lia | lia]| exact Hs
                            | cbn; reflexivity| clear; lia| clear; lia] end end.
  Qed.

End Walk.
